Translate("ptBR", "hall-of-thanes", {
	title = "Hall of Thanes",
	aliases = { "The Hall of Thanes" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Hall of Thanes fica nas cavernas sob a Velha {link:ironforge}Altaforja{/link}, muito abaixo do Alto Assento. É um lugar de tumbas e câmaras, onde os grandes anões do passado de Altaforja foram sepultados e os tesouros de seus reis foram lacrados. Por gerações, só seus guardiões andaram por ali. Agora os mortos estão inquietos, e os {link:dark-iron-dwarves}Ferro Negro{/link} invadiram por baixo.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra quando o primeiro thane foi sepultado nestes salões. As câmaras em seu ponto mais profundo são chamadas de Relicário dos Reis. Entre as relíquias guardadas ali havia uma tabuleta de pedra dos dias que se seguiram à guerra dos três clãs, quando Madoran se tornou o primeiro rei Barbabronze de {link:ironforge}Altaforja{/link}: o tratado de paz entre os Barbabronze e os Martelo Feroz, que os {link:dark-iron-dwarves}Ferro Negro{/link} se recusaram a assinar. Outra câmara, o Repouso de Anvilmar, abriga a tumba de um thane chamado {link:faldrim-anvilmar}Faldrim Anvilmar{/link}.]=],
		},
		{
			title = "A Incursão",
			text = [=[O {link:earthseer-farsen}Vidente da Terra Farsen{/link}, um Martelo Feroz em visita a {link:dun-morogh}Dun Morogh{/link}, foi o primeiro a ver o perigo. Espiões {link:dark-iron-dwarves}Ferro Negro{/link} haviam entrado na região, e um mapa tomado de seus mortos mostrava túneis que se encontravam sob {link:ironforge}Altaforja{/link}. Os Ferro Negro subiram às câmaras em máquinas-toupeira. Seus saqueadores começaram a despojar as tumbas de suas relíquias de família, seus engenheiros lançaram bombas e seus invocadores chamaram o fogo. Golens de pedra andam a seu lado. Ao mesmo tempo, os espíritos dos mortos despertaram, furiosos e atormentados, e começaram a assombrar seus próprios salões.]=],
		},
		{
			title = "Chefes",
			text = [=[• {b}{link:faldrim-anvilmar}Faldrim Anvilmar{/link}{/b}, um thane de outrora cujo espírito não encontra descanso, consumido por um antigo rancor.
• {b}{link:magmatus}Magmatus{/link}{/b}, uma criatura de fogo vivo que luta ao lado de um invocador {link:dark-iron-dwarves}Ferro Negro{/link}.
• {b}Plunder{/b}, um elemental que vaga por um salão das câmaras e arremessa os intrusos para longe.
• {b}{link:durgen-dirgehammer}Durgen Dirgehammer{/link}{/b}, o comandante da incursão Ferro Negro, guardado por golens nas câmaras inferiores.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os guardiões das tumbas não descerão ao salão até que os mortos se aquietem. Um {link:gnomes}gnomo{/link} que afirma estar patrulhando as câmaras quer que as relíquias de família sejam levadas de volta para cima, e diz que as catalogará. O {link:earthseer-farsen}Vidente da Terra Farsen{/link} pede voluntários para descer, encontrar o comandante {link:dark-iron-dwarves}Ferro Negro{/link} e levar sua cabeça ao rei. O Rei {link:magni-bronzebeard}Magni Bronzebeard{/link} prometeu que, assim que os invasores se forem, as brechas serão seladas e os salões inferiores reforçados, para que nenhum inimigo possa voltar por esse caminho.]=],
		},
	},
})

Translate("ptBR", "faldrim-anvilmar", {
