	sections = {
		{
			title = "Resumo",
			text = [=[Magmatus é uma criatura de fogo vivo que entrou no {link:hall-of-thanes}Hall of Thanes{/link} com os {link:dark-iron-dwarves}Ferro Negro{/link}. Um invocador Ferro Negro fica a seu lado, e as chamas que jorram dele envolvem todos que estão perto. Os Ferro Negro servem aos senhores do fogo desde a queda de sua cidade de {link:ruins-of-thaurissan}Thaurissan{/link}, e seus invocadores levam o fogo consigo aonde quer que vão. Nas tumbas dos thanes, entre a velha pedra de {link:ironforge}Altaforja{/link}, Magmatus arde como um sinal de quem chegou.]=],
		},
		{
			title = "Importância",
			text = [=[Magmatus mostra que a incursão {link:dark-iron-dwarves}Ferro Negro{/link} não é um mero bando de ladrões. Os que vieram para baixo de {link:ironforge}Altaforja{/link} trouxeram consigo o poder de seus senhores.]=],
		},
	},
})

